def backfill_verified_transport_receipts(apps, schema_editor):
    """Copy stored amounts only for states produced by verified callbacks or cash receipt confirmation."""
    Payment = apps.get_model("core", "TransportPayment")
    alias = schema_editor.connection.alias
    Payment.objects.using(alias).filter(
        status="confirmed", received_amount__isnull=True
    ).update(received_amount=F("amount"))
    # The existing C2B handler marked this state only after a provider callback.
    Payment.objects.using(alias).filter(
        method="c2b", status="unmatched", received_amount__isnull=True
    ).update(received_amount=F("amount"))


